WITH ship_category AS ( SELECT sm.sm_ship_mode_id, sm.sm_type, sm.sm_carrier, i.i_category, COUNT(*) AS return_cnt, SUM(cr.cr_net_loss) AS total_net_loss, SUM(cr.cr_return_amount) AS total_return_amount, AVG(cr.cr_return_quantity) AS avg_return_qty FROM catalog_returns cr JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk WHERE cr.cr_returned_date_sk BETWEEN 20200101 AND 20201231 GROUP BY sm.sm_ship_mode_id, sm.sm_type, sm.sm_carrier, i.i_category ) SELECT sm_ship_mode_id, sm_type, sm_carrier, i_category, return_cnt, total_net_loss, total_return_amount, avg_return_qty, CASE WHEN total_net_loss > 50000 THEN 'Critical' WHEN total_net_loss > 20000 THEN 'High' WHEN total_net_loss > 10000 THEN 'Medium' ELSE 'Low' END AS loss_risk, DENSE_RANK() OVER (PARTITION BY sm_ship_mode_id ORDER BY total_net_loss DESC) AS category_risk_rank FROM ship_category WHERE return_cnt >= 5 ORDER BY sm_ship_mode_id, category_risk_rank LIMIT 30
